insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('51d02fa7-7a7b-458c-a8ec-0958531966ac', 'book', 'Harrison : PRINCIPES DE MÉDECINE INTERNE (5e éd. fr.)', 'French', 1992, 'WB 115 HAR 1992', 'Médecine interne / طبعة تاريخية هامة ومستقلة باللغة الفرنسية (الطبعة الخامسة المترجمة عن الأمريكية الثانية عشرة) من مرجع "هاريسون" العالمي الشهير في الطب الباطني؛ تكمن القيمة الأكاديمية الاستثنائية لهذه النسخة في توثيقها الدقيق والشامل للآليات الإمراضية (Pathophysiology) ومبادئ الفحص السريري والمخبري لكافة المتلازمات الباطنية والجهازية في بداية التسعينيات، لاسيما التحديثات التاريخية العميقة المتعلّقة بالأمراض المعدية الناشئة آنذاك برعاية معهد الدكتور أنثوني فاوتشي، مما يجعلها مرجعاً أساسياً في رصيد المكتبات الطبية الجامعية', 'import');
