insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('0408a8dc-fd14-4005-8d20-fd632c3d6632', 'book', 'Anesthésie et réanimation en obstétrique', 'French', 1983, 'WO 450 SHN 1983', 'Anesthésie - Obstétrique / النسخة المترجمة للفرنسية بإشراف البروفيسورة "جينيفيف بارييه" لأحد أهم المراجع العالمية التأسيسية في "التخدير والإنعاش التوليدي" (Obstetric Anesthesia)؛ يستعرض الكتاب بعمق أكاديمي وتطبيقي استثنائي التأثيرات الفسيولوجية والدوائية للمخدر على الأم والجنين، التدبير الدوائي والتقني للتسكين فوق الجافية (Anesthésie péridurale) أثناء المخاض، الإدارة الطبية الدقيقة للتخدير في القيصريات الإسعافية وحالات الحمل عالي الخطورة (مثل تسمم الحمل)، بالإضافة إلى بروتوكولات "إنعاش الوليد والأم" الفورية في غرف العمليات لتأمين سلامتهم', 'import');
