insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('aa41213c-8e46-4ce1-802b-61e00c2f8005', 'book', 'diabète sucré : BASES THÉORIQUES, CLINIQUES ET THÉRAPEUTIQUES', 'French', 1981, 'WK 810 PET 1981', 'Endocrinologie - Diabétologie / [تنبيه هام: تم رصد وتوثيق خمس نسخ مكررة 5 Exemplaires من هذا الكتاب في الرصيد]؛ دليل تخصصي وأكاديمي عالي القيمة يمثل ركيزة في "علم السكري" (Diabetology)، ترجمه للعالم الفرانكوفوني البروفيسور الشهير "جيرار سلامة"؛ يفصل الكتاب بدقة كافّة الأسس البيوكيميائية والفسيولوجية لإفراز الإنسولين، الآليات الإمراضية للنمطين الأول والثاني من السكري، المعايير العيادية للتشخيص والمراقبة المخبرية المستمرة (مثل الهيموغلوبين الغليكوزي HbA1c)، التدبير الدوائي المتكامل وحساب جرعات الإنسولين، إلى جانب فصول موسعة حول سبل الوقاية والعلاج من اختلاطات السكري الوعائية والكلية والشبكية الحادة والمزمنة', 'import');
