insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('bbb85826-4cbf-469b-b5fb-77ccf8f57864', 'book', 'Précis d''échocardiographie', 'French', 2007, 'WG 141.5.E2 FLA 2007', 'Cardiologie - Imagerie médicale / دليل عيادي فرنسي-ألماني متقدم وعالي القيمة والأهمية لأطباء القلب والفنيين؛ يحتوي على 460 شكلاً وتوضيحاً فائق الدقة و42 جدولاً تلخيصياً، ويستعرض بالتفصيل المنهجي "تقنيات وأصول تخطيط صدى القلب" (Echocardiography)، بما في ذلك الفحص عبر الصدر (ETT) وعبر المريء (ETO)، تقييم الوظيفة الانقباضية والانبساطية للبطينين، حساب وتوصيف الآفات الصمامية (تضيق وقصور الصمامات)، تشخيص أمراض الشغاف وعضلة القلب، متبعاً بصرامة أحدث التوجيهات القياسية المعتمدة عالمياً لضمان دقة التقارير التشخيصية | Cardiologie / أدلة التشخيص والتصوير بالصدى للقلب | Cardiologie / دليل عيادي فرنسي-ألماني متقدم؛ يستعرض بالتفصيل تقنيات الفحص وتصوير صدى القلب (الإيكو) عبر الصدر والمريء', 'import');
