insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('0a1f4329-e514-4ae5-a973-82e6ecde813f', 'book', 'PRINCIPES OF NEURAL SCIENCE (2nd ed.)', 'French', 1985, 'WL 102 KAN 1985', 'Neurosciences - Neurologie / يُعد هذا الكتاب الأكاديمي الموسوعي الضخم بمثابة "إنجيل علم الأعصاب" والكتاب الأكثر شهرة وتأثيراً عالمياً في تاريخ هذا التخصص؛ تكمن القيمة العلمية الاستثنائية لهذه الطبعة الثانية التاريخية في صياغتها للمبادئ الحديثة التي ربطت بين "علم الأحياء الخلوي والجزيئي" وسلوك الجهاز العصبي؛ يستعرض البروفيسور الحائز على جائزة نوبل "إريك كانديل" وزميله "شينوارترز" بعمق فائق الآليات الفيزيولوجية العصبية للسيالة العصبية والناقلات، التشريح الوظيفي للمخ والنخاع الشوكي، المعالجة الحسية والحركية، والأسس البيولوجية المعقدة للذاكرة، والتعلم، والإدراك، والاضطرابات العصبية والسلوكية، مما يجعله كنزاً أكاديمياً نادراً في رصيد المكتبة الطبية الجامعية', 'import');
