insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('5134e8f6-d276-4858-a679-c3c03cd3fac3', 'book', 'les maladies systémiques (3e éd.)', 'French', 1993, 'WD 375 KAH 1993', 'Médecine interne - Rhumatologie / يُعد هذا السفر الأكاديمي التاريخي الضخم بمثابة المرجع السيادي والأكثر شهرة في الأدبيات الطبية الفرنكوفونية المكرس لـ "الأمراض الجهازية وأمراض المناعة الذاتية" (Systemic Diseases)؛ يستعرض البروفيسور الخبير "ميشيل فرانسيس كاهن" وفريقه بعمق فائق وبشكل نسقي شامل الفسيولوجيا المرضية المعقدة، المعايير التشخيصية المخبرية والسريرية، والبروتوكولات العلاجية لـ الذئبة الحمامية الجهازية (Lupus érythémateux disséminé)، متلازمة مضادات الفوسفوليبيد، تصلب الجلد المناعي، التهاب المفاصل الروماتويدي، ومتلازمات التهاب الأوعية الدموية (Vascularites)، مما يجعله عماداً مرجعياً لا غنى عنه لأطباء الباطنية والروماتيزم والمناعة', 'import');
