insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('b214a316-d052-4e95-ac8f-ba783a29b196', 'book', 'ATLAS D''ECHOEMBRYOLOGIE : Biométrie embryo-fœtale', 'French', 1993, 'WQ 17 CON 1993', 'Obstétrique - Échographie - Embryologie / أطلس طبي مصور فرنسي متقدم للغاية، يمثل أداة عيادية وتطبيقية سيادية لأطباء النساء والتوليد وأخصائيي الأشعة؛ يركز الكتاب كلياً على "علم تصوير الأجنة بالموجات فوق الصوتية" (Echoembryology)؛ يستعرض عبر مئات الصور الإكلينيكية والقياسات المرجعية مراحل التطور الجنيني والمضغي المبكر داخل الرحم أسبوعاً بأسبوع، مع تفصيل "القياسات الحيوية للجنين" (Biométrie fœtale) مثل قياس القطب الجنيني، القطر بين الجدارين، وطول الفخذ، مما يتيح الكشف المبكر عن التشوهات التطورية، ومراقبة وتحديد العمر الدقيق للحمل بدقة متناهية لضمان سلامة الأم والجنين', 'import');
