insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('29401bf0-f9c3-4a05-b9b3-3837a982726b', 'book', 'PHYSIOLOGIE (2e éd.)', 'French', 1969, 'QT 104 KAY 1969', 'Physiologie humaine / جزء ومجلد مكمل ومستقل زمنياً ينتمي لطبعة عام 1969 من نفس المطولة الفسيولوجية التأسيسية الكبرى للبروفيسور "شارل كايزر" وفريقه؛ يستعرض المجلد بعمق أكاديمي فائق القواعد الكيميائية والفيزيائية للوظائف الحيوية الإنسانية، التوازن الهرموني الغدي، آليات عمل الجهاز العصبي المركزي والمحيطي، الفسيولوجيا العضلية والقلبية، فضلًا عن آليات التنظيم الحراري والتحكم الخلوي، مشكلاً ركيزة لا غنى عنها في مكتبة العلوم الطبية الأساسية لكليات الطب', 'import');
