insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('d7107747-34fa-4ffb-ac95-d4c67f054b67', 'book', 'Petit Larousse de la Médecine : tome 1', 'French', 1976, 'W 13 DOM 1976', 'Dictionnaire médical - Encyclopédie / معجم وموسوعة طبية فرنسية تاريخية بالغة الشهرة والأهمية من فئة المعاجم الموسوعية الكبرى لدار لاروس (Larousse)؛ يُمثّل هذا الجزء الأول أداة مرجعية ببليوغرافية وتأسيسية متكاملة لطلاب العلوم الطبية والأطباء والباحثين؛ يغطي بدقة أبجدية نسقية آلاف المصطلحات الطبية والتعاريف السريرية الشاملة، مع شرح معمق للآليات الفسيولوجية، الأسماء التشريحية، المفاهيم العيادية للأمراض، والأعراض وعلامات الاستقصاء المخبري والتحاليل، مما يجعله كنزاً معرفياً لضبط وتوحيد المصطلحات الطبية الفرنسية', 'import');
