insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('6fe286b8-2e47-4dbc-8023-0fcd019dc5ec', 'book', 'LA PROTECTION CONTRE LES RAYONNEMENTS NON IONISANTS', 'French', 1985, 'WA 470 SUE 1985', 'Santé publique - Radioprotection / تقرير فني وموسوعي سيادي عالي الأهمية صادر رسمياً باللغة الفرنسية عن منظمة الصحة العالمية (OMS) بالاشتراك مع برنامج الأمم المتحدة للبيئة (PNUE)؛ يُعد بمثابة الدليل المرجعي الأساسي في "الصحة البيئية والوقاية الإشعاعية" (Radiation Protection)؛ يغطي الكتاب بأسلوب علمي صارم المعايير الدولية والحدود الآمنة للتعرض للموجات الكهرومغناطيسية، والأشعة فوق البنفسجية، والأشعة تحت الحمراء، وأشعة الليزر، والموجات الدقيقة (Microwaves)، متناولاً بالتفصيل تأثيراتها الحيوية والسريرية على الأنسجة البشرية (العين والجلد) ووضع آليات الوقاية الهندسية والطبية الصارمة لحماية العاملين وعموم الجمهور من المخاطر البيئية والمهنية للإشعاعات غير المؤينة', 'import');
