insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('443f7db8-4911-4088-95b8-d4ae7560a92b', 'book', 'COVID-19 : Du Diagnostic... à la Prise en Charge Thérapeutique', 'French', 2021, 'WC 505 ABB 2021', 'Virologie - Épidémiologie - Gestion de Crise / مصنف طبي سيادي ومونوغراف وطني جزائري معاصر بالغ الأهمية؛ يوثق بدقة علمية وتنظيمية تجربة المنظومة الصحية الجزائرية وتحديدا المركز الاستشفائي الجامعي لباب الوادي (CHUBEO) في مواجهة جائحة "كوفيد-19" (COVID-19)؛ يستعرض الكتاب الخطط العيادية المتقدمة من آليات التشخيص المبكر والمسوح المخبرية والتصوير المقطعي للصدر، مروراً بـ "التكفل العلاجي والبروتوكولات الدوائية" المقرة، وصولاً إلى استراتيجيات "إدارة الأزمات الطبية وتنسيق الطوارئ" (Crisis Management) وتطوير مرونة الأطقم الطبية، وتثبيت التوصيات الرسمية الوطنية لمجابهة الأوبئة الفيروسية المستجدة وحماية الصحة العامة', 'import');
