insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('32d020c2-98b8-4440-ace5-2a3dd0bac74b', 'book', 'MALADIES DES VOIES BILIAIRES ET DU PANCREAS (Tome II)', 'French', 1993, 'WI 700 HES 1993', 'Gastro-entérologie - Chirurgie digestive / [المجلد الثاني من الموسوعة]؛ يُكمل هذا الجزء التتابعي الببليوغرافي (المجلد الثاني) الأطروحة الموسوعية والجراحية الكبرى لـ "والتر هيس" وزملائه؛ يركز هذا المجلد تحديداً على تقنيات الاستقصاء السريري المتقدم والتشخيص الإشعاعي والمخبري والمنظاري التفصيلي (Endoscopie et Cholangiographie) لآفات الشجرة المرارية والبنكرياس، مع تفصيل هندسة التدخلات الجراحية الكلاسيكية والوقاية من الاختلاطات النزفية والصفراوية أثناء العمليات لضمان أقصى درجات السلامة السريرية', 'import');
