insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('db1fe569-14f2-4851-8bc2-1138fd007abe', 'book', 'ACTUALITÉS EN RÉANIMATION ET URGENCES 1995', 'French', 1995, 'WX 218 SRL 1995', 'Réanimation - Soins intensifs - Urgences / [طبعة تتابعية مكملة لعام 1995]؛ سِفر طبي وأكاديمي سنوي سيادي رفيع المستوى ومحكّم؛ يُمثّل الخلاصة الرسمية المحدثة لأبحاث ومستجدات الجمعية الفرنكوفونية للعناية المركزة (SRLF)؛ يستهدف هذا المجلد كافّة الأطباء المقيمين وأخصائيي التخدير والإنعاش وطب الطوارئ؛ ويغطي بعمق عيادي متقدم للغاية المعطيات العلمية والبروتوكولات الجديدة لتدبير حالات القصور التنفسي الحاد، الصدمات القلبية والإنتانية المتقدمة، الإنعاش الاستعجالي العصبي، التسممات الحادة، واختلالات التوازن الشاردي الخلوي، مشكلاً الأداة التوجيهية الأعلى داخل غرف العناية المركزة وأقسام الإنعاش', 'import');
