insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('268a81f5-d2fe-4eaa-954a-5a194f0efa91', 'book', 'INSUFFISANCE CIRCULATOIRE AIGUË', 'French', 1994, 'WG 106 RIC 1994', 'Réanimation - Cardiologie critique / دراسة مونوغرافية طبية وأكاديمية رفيعة القيمة وعالية التخصص؛ تُعد من الركائز التأسيسية الكبرى للأطباء المقيمين وأخصائيي التخدير والإنعاش وطب القلب الحرج؛ تركز بالكامل على فك الآليات المعقدة لـ "قصور الدورة الدموية الحاد وحالات الصدمة" (Circulatory Failure & Shock)؛ يستعرض الكتاب بأسلوب عيادي وفسيولوجي مرضى صارم آليات المراقبة الهيموديناميكية المتقدمة (Monitorage hémodynamique) كقثطرة الشريان الرئوي، تقييم نقص الأكسجة النسيجي، التدبير الدوائي المعقد بواسطة المقويات القلبية ومضيقّات الأوعية (Catécholamines)، والتعامل الطبي الدقيق مع الصدمة الإنتانية (Choc septique)، الصدمة قلبية المنشأ، والنزفية، مما يجعله الدليل التشغيلي الأعلى لضبط القرارات الإسعافية الفورية داخل غرف العناية المركزة', 'import');
