insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('1b65d7fd-446a-472a-99a4-201c945de55c', 'book', 'LES CANCERS DU MASSIF MAXILLAIRE SUPÉRIEUR : ÉTUDE ANATOMO-CLINIQUE ET THÉRAPEUTIQUE', 'French', 1961, 'WE 705 HUE 1961', 'Oncologie maxillo-faciale - ORL / دراسة مونوغرافية طبية وأكاديمية تاريخية فائقة الأهمية والقيمة العلمية صادرة عن دار MASSON؛ تُعد من أمهات المراجع التأسيسية في أورام الوجه والفكين؛ تركز بالكامل على "سرطانات الفك العلوي والجيوب الأنفية" (Maxillary & Sinus Neoplasms)؛ يقدم البروفيسور "هيو" وزملائه تحليلاً تشريحياً وسريرياً صارماً للغزو الورمي، معايير التصنيف والتغليف الجراحي، واستراتيجيات الجمع بين الاستئصال الجراحي الفكي والعلاج الإشعاعي الموجه لتأمين أفضل نسب البقاء', 'import');
