insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('5baaa981-e1cc-4bf7-9cb2-fea42f12e899', 'book', 'Atlas de l''agrafage chirurgical', 'French', 2000, 'WO 500 FEI 2000', 'Chirurgie générale & digestive - Techniques chirurgicales / أطلس جراحي متقدم وعالي التخصص؛ صادر عن دار Johann Ambrosius Barth؛ مخصص لجراحي الجهاز الهضمي والقلب والصدر والجراحة العامة؛ يركز بالتفصيل والرسوم التوضيحية الدقيقة على "تقنيات التدبيس الجراحي الأوتوماتيكي والمفاغرة الميكانيكية" (Surgical Stapling) في جراحات المريء، المعدة، الأمعاء، القولون والمستقيم، والريئة؛ مع شرح الخطوات التشريحية والتطبيقية لتجنب التسريب والمضاعفات الجراحية', 'import');
