insert into books (id, item_type, title, language, publication_year, call_number, notes, source) values ('d46d0933-9e3c-486f-927d-63e963668991', 'book', 'ATLAS D''ANATOMIE PATHOLOGIQUE DU SYSTÈME NERVEUX', 'French', 1981, 'WL 17 HIR 1981', 'Neuropathologie - Anatomie pathologique / [تنبيه: تم رصد وتوثيق نسختين مكررتين 2 Exemplaires من هذا الكتاب]؛ أطلس مرجعي ونادر فائق الأهمية العلمية والتشخيصية؛ صادر عن دار MEDSI؛ يُمثّل أطلس المجهر والأورام العصبية الأسطوري لعالم التشريح المرضي العالمي "آساو هيرانو" (Asao Hirano)؛ موجه لأخصائيي التشريح المرضي وأطباء الأعصاب وجراحي المخ والأعصاب؛ يضم مئات الصور المجهرية المقفية الملونة للآفات النسيجية العصبيّة، أورام الدماغ والنخاع الشوكي (Gliomes, Méningiomes)، التغيرات التنكسية العصبية (Alzheimer, Parkinson)، الإصابات الوعائية الدماغية، والالتهابات الخمجية للجهاز العصبي', 'import');
